import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new file inside {@code dir} with a unique name derived from {@code name}.
     * The method protects against directory‑traversal attacks by normalizing the
     * resolved path and ensuring it stays within {@code dir}.  If the supplied
     * {@code name} would resolve outside {@code dir}, an {@link IllegalArgumentException}
     * is thrown.
     *
     * @param dir  the target directory where the file should be created
     * @param name the desired file name (may contain a query string)
     * @return a {@link File} instance pointing to a non‑existing file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is null,
     *                                  empty, or the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested path against the target directory
        Path dirPath = dir.toPath().normalize();
        Path resolvedPath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still under the target directory
        if (!resolvedPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempt to create a file outside the target directory: " + name);
        }

        // Prepare for unique naming
        String baseName = resolvedPath.getFileName().toString();
        int dot = baseName.indexOf('.');
        String prefix = dot < 0 ? baseName : baseName.substring(0, dot);
        String suffix = dot < 0 ? "" : baseName.substring(dot);

        File file = resolvedPath.toFile();
        int index = 2;
        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            Path newPath = resolvedPath.getParent().resolve(newName);
            file = newPath.toFile();
        }

        // Create any missing parent directories
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods
}
```

