        }

        // Tokenise the incoming URL string
        String[] resourceUrls = StringUtils.tokenizeToStringArray(resourceUrl, RESOURCE_URL_DELIMITERS);

        // Resolve the context root once for later containment checks
        String contextRootPath = request.getServletContext().getRealPath("/");
        File contextRoot = (contextRootPath != null) ? new File(contextRootPath).getCanonicalFile() : null;

        for (String url : resourceUrls) {
            String trimmed = url.trim();
            if (trimmed.isEmpty()) {
                continue; // ignore empty tokens
            }

            // Normalise the path to eliminate '..' segments
            Path normalizedPath = Paths.get(trimmed).normalize();

            // Reject any path that attempts to traverse upwards
            if (normalizedPath.startsWith("..") || normalizedPath.toString().contains("..")) {
