    /**
     * Establishes a secure LDAP context using STARTTLS and performs an explicit bind
     * with the supplied principal and credentials. The method validates that the
     * credentials are accepted by the server before returning the context.
     *
     * @param ldapContextFactory factory providing LDAP configuration
     * @param principal          the distinguished name or username to bind as
     * @param credentials        the password or credential object
     * @return an authenticated {@link LdapContext} secured with TLS
     * @throws NamingException if the connection or authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(
            LdapContextFactory ldapContextFactory,
            Object principal,
            Object credentials) throws NamingException {

        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("Principal and credentials must not be null");
        }

