/**
 * Utility class for extracting archive entries into a target directory.
 * <p>
 * The {@code expand} method has been hardened against path‑traversal attacks.
 * It now performs strict validation of entry names, normalises paths using
 * {@link Path}, and ensures that every resolved path remains within the
 * intended extraction directory.
 */
public class Expander {

    // other methods

    /**
     * Extracts all readable entries from the supplied archive into the
     * specified target directory.
     *
     * @param supplier      provides the next {@link ArchiveEntry} to extract
     * @param writer        writes the entry data to the output stream
     * @param targetDirectory the directory into which entries are extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical (real) path of the target directory once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            String entryName = nextEntry.getName();

            /* ------------------------------------------------------------------
             * 1. Basic sanity checks on the entry name
             * ------------------------------------------------------------------ */
            // Reject absolute paths (leading '/' or '\\') and Windows drive letters.
            if (entryName.startsWith("/") ||
                entryName.startsWith("\\") ||
                entryName.contains(":")) {
                throw new IOException("Invalid entry name (absolute path or drive letter): " + entryName);
            }

            // Reject empty names or names that resolve to '.' or '..'
            if (entryName.isEmpty() ||
                entryName.equals(".") ||
                entryName.equals("..")) {
                throw new IOException("Invalid entry name: " + entryName);
            }

            /* ------------------------------------------------------------------
             * 2. Resolve the entry path against the target directory
             * ------------------------------------------------------------------ */
            Path resolvedPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still under the target directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException(
                    "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            File f = resolvedPath.toFile();

            /* ------------------------------------------------------------------
             * 3. Handle directories and files
             * ------------------------------------------------------------------ */
            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                File parent = f.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                try (OutputStream o = Files.newOutputStream(f.toPath())) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
