private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – the data is cached in
    // lastStoredEntry and can be read directly.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // populate lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Defensive checks – a negative or unreasonably large size indicates a corrupt
    // or malicious archive. Throwing an exception prevents an infinite read loop.
    if (csize < 0 || csize > Integer.MAX_VALUE) {
        throw new IOException("Invalid entry size: " + csize);
    }

    // If we've already read the declared amount, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Refill the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            // Unexpected end of stream – treat as EOF for this entry.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;

        // Detect a mismatch between the declared size and the actual data
        // read so far. This protects against archives that claim a larger
        // size than the data actually contains.
        if (current.bytesReadFromStream > csize) {
            throw new IOException("Entry size mismatch: read " + current.bytesReadFromStream
                    + " bytes but declared size is " + csize);
        }
    }

    // Determine how many bytes to copy from the buffer.
    int toRead = Math.min(buf.remaining(), length);

    // Do not read past the declared size of the entry.
    long remaining = csize - current.bytesRead;
    if (remaining < toRead) {
        toRead = (int) remaining;
    }

    // If there is nothing left to read, signal EOF.
    if (toRead <= 0) {
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
