import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods

    /**
     * Determines whether the incoming request is allowed to modify the specified SCIM user.
     *
     * <p>Security enhancements:</p>
     * <ul>
     *   <li>Ensures the authenticated user is the owner of the account being updated.</li>
     *   <li>Uses {@link Objects#equals(Object,Object)} for null‑safe comparisons.</li>
     *   <li>Rejects updates that attempt to change the primary email to one that belongs to another user.</li>
     * </ul>
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is permitted, {@code false} otherwise
     * @throws IOException if an I/O error occurs while reading the request body
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // Read the request body once
        String requestBody = IOUtils.toString(request.getReader());

        // Deserialize the incoming SCIM user representation
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // Extract the target user ID from the URL path
        String id = UaaUrlUtils.extractPathVariableFromUrl(USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // Retrieve the current state of the user from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation to proceed (e.g., creation)
            return true;
        }

        // --------------------------------------------------------------------
        // 1️⃣  Verify that the request is made by the account owner
        // --------------------------------------------------------------------
        String authenticatedUserName = getAuthenticatedUserName(request);
        if (!Objects.equals(authenticatedUserName, scimUserFromDb.getUserName())) {
            // The caller is not the owner of the account – deny the update
            return false;
        }

        // --------------------------------------------------------------------
        // 2️⃣  Validate that the primary email is unchanged unless verified
        // --------------------------------------------------------------------
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            // Email change is not allowed without additional verification
            return false;
        }

        // --------------------------------------------------------------------
        // 3️⃣  Validate remaining fields
        // --------------------------------------------------------------------
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed
        return true;
    }

    /**
     * Retrieves the authenticated user's identifier from the request.
     *
     * <p>This implementation assumes that the servlet container has performed authentication
     * and populated {@link HttpServletRequest#getUserPrincipal()} with the authenticated
     * principal. If no principal is present, {@code null} is returned.</p>
     *
     * @param request the HTTP request
     * @return the authenticated user's username or {@code null} if unauthenticated
     */
    private String getAuthenticatedUserName(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        return principal != null ? principal.getName() : null;
    }

    // other methods
}
